}

function validRebaseRow(registration: V3PlaneRegistration, classified: ClassifiedRebaseRow): boolean {
	const historical = classified.kind === "covered-historical" || classified.kind === "pinned-genesis";
	const source =
		classified.kind === "current"
			? registration.payload
			: historical
				? registration.payload
				: (registration.displacedSource?.prepared ?? registration.payload);
	if (source === undefined || !hasBoundedDependencies(source, classified.authenticated)) return false;
	const operation = classified.authenticated.vertex.operation;
	if (operation === undefined) return false;
	const settlementSourceControl =
		settlementProfileFor(registration.payload.trust.trust.profileId) === "v1" &&
		(isControlOperation(operation, registration.payload.trust.trust.profileId) ||
			Reflect.get(operation, "action") === "acl");
	return (
		settlementSourceControl ||
		acceptedApplicationOperation(source, operation, classified.authenticated.admitted.logicalTime)
	);
}

function rebaseIntents(
	payload: PreparedV3LivePayload,
	authenticated: AuthenticatedRecoveryVertex
):
	| readonly Readonly<{
			readonly logicalTime: number;
			readonly operation: Readonly<Record<string, unknown>>;
			readonly operationCount: number;
			readonly operationIndex: number;
	  }>[]
	| undefined {
	const sourceOperation = authenticated.vertex.operation;
	if (sourceOperation === undefined) return undefined;
	const action = Reflect.get(sourceOperation, "action");
	const batch = applicationBatchEntries(payload, sourceOperation);
	if (action === APPLICATION_BATCH_ACTION) {
		return batch?.map((entry, operationIndex) =>
			ObjectFreeze({ ...entry, operationCount: batch.length, operationIndex })
		);
	}
	if (
		isControlOperation(sourceOperation, payload.trust.trust.profileId) ||
		(typeof action === "string" &&
			isReservedBatchAction(action) &&
			settlementProfileFor(payload.trust.trust.profileId) !== "v1")
	) {
		return ObjectFreeze([]);
	}
	const operation = detachedCanonicalOperation(sourceOperation);
	return operation === undefined
		? undefined
		: ObjectFreeze([
				ObjectFreeze({
					logicalTime: authenticated.admitted.logicalTime,
					operation,
					operationCount: 1,
					operationIndex: 0,
				}),
			]);
}

